app/ui/pages/for_you.py.ForYouPage.on_search_text_changed:
def on_search_text_changed(self, text):
        self.search_timer.stop()
        if not text.strip():
            self.execute_filter()
        else:
            self.search_timer.start(300)

app/ui/pages/for_you.py.LazyThumb.event:
def event(self, event):
        handled = super().event(event)
        if event.type() == QEvent.DevicePixelRatioChange and hasattr(self, "cache_key"):
            self._is_loaded = False
            if self._current_worker:
                self._current_worker.cancel()
            QTimer.singleShot(50, self._start_async_loading)
        return handled
